/**
 * Type definitions for fluent If-ElseIf-Else API
 */
/**
 * Function type for condition evaluation and body execution
 */
type ConditionalBodyFunction = () => void;
type FlowLogicParams = Now.Internal.WithID<{
    condition: string;
    label?: string;
    annotation?: string;
}>;
type FlowElseParams = Omit<FlowLogicParams, 'condition' | 'label'>;
/**
 * ElseIf function used in Flow Logic
 * @param params - object containing:
 *   - condition - String condition to evaluate
 *   - $id - Unique identifier for the record, typically using `Now.ID["value"]`
 *   - label - Optional label for the ElseIf branch
 *   - annotation - Optional annotation/description for the ElseIf branch
 * @param body - Function to execute if condition is true
 * @returns void
 */
export declare function ElseIf(_params: FlowLogicParams, _body: ConditionalBodyFunction): void;
/**
 * Else function used in Flow Logic
 * @param params - object containing:
 *   - $id - Unique identifier for the record, typically using `Now.ID["value"]`
 *   - annotation - Optional annotation/description for the Else branch
 * @param body - Function to execute if no previous conditions were true
 * @returns void
 */
export declare function Else(_params: FlowElseParams, _body: ConditionalBodyFunction): void;
/**
 * If function used in Flow Logic
 * @param params - object containing:
 *   - condition - String condition to evaluate
 *   - $id - Unique identifier for the record, typically using `Now.ID["value"]`
 *   - label - Optional label for the If branch
 *   - annotation - Optional annotation/description for the If branch
 * @param body - Function to execute if condition is true
 * @returns void
 */
export declare function If(_params: FlowLogicParams, _body: ConditionalBodyFunction): {
    type: 'if';
};
export {};
